using System.Globalization;

namespace LoopbackTranscriber.Services;

public sealed class Strings : System.ComponentModel.INotifyPropertyChanged
{
    public static Strings Instance { get; } = new();

    public event System.ComponentModel.PropertyChangedEventHandler? PropertyChanged;
    public event EventHandler? LanguageChanged;

    private string _language = "es";

    public string Language => _language;

    public string this[string key] => Get(key);

    public string Get(string key) => GetIn(_language, key);

    public string GetIn(string language, string key)
    {
        if (Translations.TryGetValue(key, out var byLanguage))
        {
            if (byLanguage.TryGetValue(language, out var text))
            {
                return text;
            }

            if (byLanguage.TryGetValue("en", out var fallback))
            {
                return fallback;
            }
        }

        return key;
    }

    public string Format(string key, params object?[] args) => string.Format(CultureInfo.CurrentCulture, Get(key), args);

    public string FormatIn(string language, string key, params object?[] args) => string.Format(CultureInfo.CurrentCulture, GetIn(language, key), args);

    public void SetLanguage(string language)
    {
        if (string.Equals(_language, language, StringComparison.OrdinalIgnoreCase))
        {
            return;
        }

        _language = language;
        PropertyChanged?.Invoke(this, new System.ComponentModel.PropertyChangedEventArgs("Item[]"));
        LanguageChanged?.Invoke(this, EventArgs.Empty);
    }

